// ──────────────────────────── tests ──────────────────────────────────────

test('plain data survives untouched', () => {
  eq(roundTrip({ id: 7, name: 'ada', tags: ['a', 'b'], ok: true, x: null }), {
    id: 7,
    name: 'ada',
    tags: ['a', 'b'],
    ok: true,
    x: null,
  });
});

test('a Date comes back as a string, not a Date', () => {
  const out = roundTrip({ when: new Date(0) });
  eq(out.when, '1970-01-01T00:00:00.000Z');
  ok(!(out.when instanceof Date));
});

test('NaN and Infinity become null', () => {
  eq(roundTrip({ a: NaN, b: Infinity, c: -Infinity }), {
    a: null,
    b: null,
    c: null,
  });
});

test('undefined and function values vanish from objects', () => {
  eq(roundTrip({ id: 1, tmp: undefined, run: () => {} }), { id: 1 });
});

test('but inside an array the same values become null', () => {
  eq(roundTrip({ list: [1, undefined, 2] }), { list: [1, null, 2] });
});

test('a Map serializes to an empty object — the data is gone', () => {
  eq(roundTrip({ m: new Map([['a', 1]]), s: new Set([1, 2]) }), {
    m: {},
    s: {},
  });
});

test('lostKeys names exactly the keys that disappear', () => {
  eq(lostKeys({ id: 1, cb: () => {}, tmp: undefined, sym: Symbol('x') }), [
    'cb',
    'tmp',
    'sym',
  ]);
});

test('lostKeys is empty when nothing is lost', () => {
  eq(lostKeys({ id: 1, name: 'ada', m: new Map() }), []);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('sorts keys at the top level', () => {
  eq(stableStringify({ b: 1, a: 2, c: 3 }), '{"a":2,"b":1,"c":3}');
});

test('sorts keys at every depth', () => {
  eq(
    stableStringify({ outer: { z: 1, a: { y: 2, b: 3 } } }),
    '{"outer":{"a":{"b":3,"y":2},"z":1}}'
  );
});

test('array order is data — it is never sorted', () => {
  eq(stableStringify([3, 1, 2]), '[3,1,2]');
  eq(stableStringify({ ids: ['c', 'a', 'b'] }), '{"ids":["c","a","b"]}');
});

test('sorts objects nested inside arrays', () => {
  eq(stableStringify({ a: [{ z: 1, y: 2 }] }), '{"a":[{"y":2,"z":1}]}');
});

test('primitives and null pass straight through', () => {
  eq(stableStringify(42), '42');
  eq(stableStringify('hi'), '"hi"');
  eq(stableStringify(null), 'null');
  eq(stableStringify({ x: null }), '{"x":null}');
});

test('two independently built objects produce identical bytes', () => {
  const built = {};
  built.zone = 'eu';
  built.id = 3;
  eq(stableStringify(built), stableStringify({ id: 3, zone: 'eu' }));
  ok(stableStringify(built) === '{"id":3,"zone":"eu"}');
});

test('sameContent ignores key order but not values', () => {
  ok(sameContent({ a: 1, b: 2 }, { b: 2, a: 1 }));
  ok(!sameContent({ a: 1, b: 2 }, { a: 1, b: 3 }));
  ok(sameContent({ a: 1 }, { a: 1, b: undefined }));
});

// ──────────────────────────── tests ──────────────────────────────────────

test('leaves an ordinary field alone', () => {
  eq(escapeCsvField('plain'), 'plain');
  eq(escapeCsvField(36), '36');
});

test('quotes a field containing a comma', () => {
  eq(escapeCsvField('Bond, James'), '"Bond, James"');
});

test('doubles the quotes inside a quoted field', () => {
  eq(escapeCsvField('say "hi"'), '"say ""hi"""');
});

test('quotes a field containing a newline', () => {
  eq(escapeCsvField('line1\nline2'), '"line1\nline2"');
  eq(escapeCsvField('line1\r\nline2'), '"line1\r\nline2"');
});

test('null and undefined become empty fields', () => {
  eq(escapeCsvField(null), '');
  eq(escapeCsvField(undefined), '');
  eq(escapeCsvField(''), '');
});

test('writes a header from the first row and one line per row', () => {
  eq(
    toCsv([
      { name: 'ada', age: 36 },
      { name: 'grace', age: 45 },
    ]),
    'name,age\nada,36\ngrace,45\n'
  );
});

test('an explicit column list picks and orders the fields', () => {
  const rows = [{ name: 'ada', age: 36, secret: 'x' }];
  eq(toCsv(rows, ['age', 'name']), 'age,name\n36,ada\n');
  eq(toCsv([], ['age', 'name']), 'age,name\n');
});

test('missing keys and nasty values still line up', () => {
  eq(
    toCsv([{ name: 'a,b', note: 'he said "no"' }, { name: 'solo' }]),
    'name,note\n"a,b","he said ""no"""\nsolo,\n'
  );
  eq(toCsv([]), '');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('splits plain rows and fields', () => {
  eq(parseCsvRows('a,b\n1,2\n'), [
    ['a', 'b'],
    ['1', '2'],
  ]);
});

test('a trailing newline does not add an empty row', () => {
  eq(parseCsvRows('only\n'), [['only']]);
  eq(parseCsvRows(''), []);
});

test('empty fields survive, including at the end of a row', () => {
  eq(parseCsvRows('a,,c\n'), [['a', '', 'c']]);
  eq(parseCsvRows('a,\n'), [['a', '']]);
});

test('a comma inside quotes is data, not a separator', () => {
  eq(parseCsvRows('"Bond, James",007\n'), [['Bond, James', '007']]);
});

test('doubled quotes decode to one quote', () => {
  eq(parseCsvRows('"say ""hi""",x\n'), [['say "hi"', 'x']]);
  eq(parseCsvRows('""\n'), [['']]);
});

test('a newline inside quotes stays inside the field', () => {
  eq(parseCsvRows('"two\nlines",z\n'), [['two\nlines', 'z']]);
});

test('handles Windows CRLF row endings', () => {
  eq(parseCsvRows('a,b\r\n1,2\r\n'), [
    ['a', 'b'],
    ['1', '2'],
  ]);
});

test('parseCsv maps the header row onto objects', () => {
  eq(parseCsv('name,note\nada,"a,b"\ngrace,"said ""no"""\n'), [
    { name: 'ada', note: 'a,b' },
    { name: 'grace', note: 'said "no"' },
  ]);
  eq(parseCsv(''), []);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('writes one JSON object per line, each ending in a newline', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'events.jsonl');
    await appendRecord(file, { id: 1 });
    await appendRecord(file, { id: 2 });
    eq(await fs.readFile(file, 'utf8'), '{"id":1}\n{"id":2}\n');
  });
});

test('reads the records back in append order', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'events.jsonl');
    await appendRecord(file, { id: 1, kind: 'open' });
    await appendRecord(file, { id: 2, kind: 'close' });
    eq(await readRecords(file), [
      { id: 1, kind: 'open' },
      { id: 2, kind: 'close' },
    ]);
  });
});

test('a missing file reads as an empty log, not an error', async () => {
  await withTempDir(async (dir) => {
    eq(await readRecords(path.join(dir, 'nope.jsonl')), []);
  });
});

test('blank lines are skipped', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'events.jsonl');
    await fs.writeFile(file, '{"id":1}\n\n   \n{"id":2}\n', 'utf8');
    eq(await readRecords(file), [{ id: 1 }, { id: 2 }]);
  });
});

test('appendRecords writes the whole batch in a single call', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'events.jsonl');
    await appendRecords(file, [{ id: 1 }, { id: 2 }, { id: 3 }]);
    eq(await readRecords(file), [{ id: 1 }, { id: 2 }, { id: 3 }]);
    eq(await fs.readFile(file, 'utf8'), '{"id":1}\n{"id":2}\n{"id":3}\n');
  });
});

test('appending never rewrites what is already there', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'events.jsonl');
    await appendRecords(file, [{ id: 1 }]);
    const before = await fs.readFile(file, 'utf8');
    await appendRecord(file, { id: 2 });
    const after = await fs.readFile(file, 'utf8');
    ok(after.startsWith(before), 'the old bytes must still be at the front');
  });
});

test('a newline inside a string does not break the format', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'events.jsonl');
    await appendRecord(file, { note: 'two\nlines' });
    await appendRecord(file, { note: 'after' });
    eq(await fs.readFile(file, 'utf8'), '{"note":"two\\nlines"}\n{"note":"after"}\n');
    eq(await readRecords(file), [{ note: 'two\nlines' }, { note: 'after' }]);
  });
});

test('an empty batch leaves the file alone', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'events.jsonl');
    await appendRecords(file, []);
    eq(await readRecords(file), []);
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('yields every record, in file order', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'events.jsonl');
    await writeLog(file, [{ id: 1 }, { id: 2 }, { id: 3 }]);
    const seen = [];
    for await (const rec of streamRecords(file)) seen.push(rec);
    eq(seen, [{ id: 1 }, { id: 2 }, { id: 3 }]);
  });
});

test('skips blank lines and tolerates a missing final newline', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'events.jsonl');
    await fs.writeFile(file, '{"id":1}\n\n{"id":2}', 'utf8');
    const seen = [];
    for await (const rec of streamRecords(file)) seen.push(rec);
    eq(seen, [{ id: 1 }, { id: 2 }]);
  });
});

test('countWhere counts the matching records', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'events.jsonl');
    await writeLog(file, [
      { level: 'info' },
      { level: 'error' },
      { level: 'error' },
      { level: 'warn' },
    ]);
    eq(await countWhere(file, (r) => r.level === 'error'), 2);
    eq(await countWhere(file, () => false), 0);
  });
});

test('handles a log far bigger than the number of lines you can eyeball', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'big.jsonl');
    await writeLog(
      file,
      Array.from({ length: 2000 }, (_, i) => ({ id: i, even: i % 2 === 0 }))
    );
    eq(await countWhere(file, (r) => r.even), 1000);
  });
});

test('findFirst returns the first matching record', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'events.jsonl');
    await writeLog(file, [{ id: 1 }, { id: 2 }, { id: 3 }]);
    eq(await findFirst(file, (r) => r.id > 1), { id: 2 });
  });
});

test('findFirst stops reading as soon as it matches', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'events.jsonl');
    await writeLog(file, Array.from({ length: 50 }, (_, i) => ({ id: i })));
    const pred = spy((r) => r.id === 1);
    eq(await findFirst(file, pred), { id: 1 });
    eq(pred.callCount, 2, 'it must not look at records after the match');
  });
});

test('findFirst returns undefined when nothing matches', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'events.jsonl');
    await writeLog(file, [{ id: 1 }]);
    eq(await findFirst(file, () => false), undefined);
  });
});

test('a missing file streams as nothing at all', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'nope.jsonl');
    eq(await countWhere(file, () => true), 0);
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('creates a file that did not exist', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'config.json');
    eq(await writeFileAtomic(file, 'hello'), file);
    eq(await fs.readFile(file, 'utf8'), 'hello');
  });
});

test('replaces the contents of an existing file', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'config.json');
    await fs.writeFile(file, 'v1', 'utf8');
    await writeFileAtomic(file, 'v2');
    eq(await fs.readFile(file, 'utf8'), 'v2');
  });
});

test('leaves no temp files behind', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'config.json');
    await writeFileAtomic(file, 'a');
    await writeFileAtomic(file, 'b');
    await writeFileAtomic(file, 'c');
    eq(await fs.readdir(dir), ['config.json']);
  });
});

test('writeJsonAtomic round trips a value', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'db.json');
    await writeJsonAtomic(file, { users: ['ada'], hits: 2 });
    eq(JSON.parse(await fs.readFile(file, 'utf8')), { users: ['ada'], hits: 2 });
  });
});

test('a value that cannot be serialized rejects', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'db.json');
    const circular = { name: 'loop' };
    circular.self = circular;
    await rejects(() => writeJsonAtomic(file, circular));
  });
});

test('a failed write leaves the previous file byte-for-byte intact', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'db.json');
    await writeJsonAtomic(file, { good: true });
    const before = await fs.readFile(file, 'utf8');
    const circular = { name: 'loop' };
    circular.self = circular;
    await rejects(() => writeJsonAtomic(file, circular));
    eq(await fs.readFile(file, 'utf8'), before);
    ok(before.length > 0, 'the old file must not be truncated');
  });
});

test('a failed write leaves no temp file either', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'db.json');
    await writeJsonAtomic(file, { good: true });
    const circular = {};
    circular.self = circular;
    await rejects(() => writeJsonAtomic(file, circular));
    eq(await fs.readdir(dir), ['db.json']);
  });
});

test('writes into a directory that does not exist reject loudly', async () => {
  await withTempDir(async (dir) => {
    await rejects(() => writeFileAtomic(path.join(dir, 'nope', 'a.txt'), 'x'));
    eq(await fs.readdir(dir), []);
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('opening a file that does not exist starts empty and clean', async () => {
  await withTempDir(async (dir) => {
    const store = await JsonStore.open(path.join(dir, 'settings.json'));
    eq(store.size, 0);
    eq(store.dirty, false);
    eq(store.get('theme'), undefined);
  });
});

test('set and get work in memory before any save', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'settings.json');
    const store = await JsonStore.open(file);
    store.set('theme', 'dark');
    store.set('fontSize', 14);
    eq(store.get('theme'), 'dark');
    eq(store.size, 2);
    ok(store.has('fontSize'));
    eq(await fs.readdir(dir), [], 'nothing is on disk until save()');
  });
});

test('save writes JSON a fresh open reads back', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'settings.json');
    const store = await JsonStore.open(file);
    store.set('theme', 'dark');
    await store.save();

    const reopened = await JsonStore.open(file);
    eq(reopened.get('theme'), 'dark');
    eq(reopened.dirty, false);
  });
});

test('dirty flips on change and clears on save', async () => {
  await withTempDir(async (dir) => {
    const store = await JsonStore.open(path.join(dir, 'settings.json'));
    eq(store.dirty, false);
    store.set('a', 1);
    eq(store.dirty, true);
    await store.save();
    eq(store.dirty, false);
  });
});

test('delete removes a key and marks the store dirty', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'settings.json');
    const store = await JsonStore.open(file);
    store.set('a', 1);
    await store.save();
    eq(store.delete('a'), true);
    eq(store.has('a'), false);
    eq(store.dirty, true);
    await store.save();
    eq((await JsonStore.open(file)).size, 0);
  });
});

test('deleting a key that is not there changes nothing', async () => {
  await withTempDir(async (dir) => {
    const store = await JsonStore.open(path.join(dir, 'settings.json'));
    eq(store.delete('ghost'), false);
    eq(store.dirty, false);
  });
});

test('save on a clean store does not touch the file', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'settings.json');
    const store = await JsonStore.open(file);
    store.set('a', 1);
    await store.save();

    // somebody else edits the file; a no-op save must not clobber it
    await fs.writeFile(file, '{"a":1,"edited":true}', 'utf8');
    await store.save();
    eq(await fs.readFile(file, 'utf8'), '{"a":1,"edited":true}');
  });
});

test('toObject hands back a copy, not the internals', async () => {
  await withTempDir(async (dir) => {
    const store = await JsonStore.open(path.join(dir, 'settings.json'));
    store.set('a', 1);
    const snapshot = store.toObject();
    eq(snapshot, { a: 1 });
    snapshot.a = 999;
    eq(store.get('a'), 1);
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('applyOp writes a key into the state', () => {
  const state = { a: 1 };
  applyOp(state, { op: 'set', key: 'b', value: 2 });
  eq(state, { a: 1, b: 2 });
});

test('applyOp removes a key, and tolerates removing a missing one', () => {
  const state = { a: 1 };
  applyOp(state, { op: 'delete', key: 'a' });
  applyOp(state, { op: 'delete', key: 'ghost' });
  eq(state, {});
});

test('an unknown op type is a bug, not a shrug', () => {
  throws(() => applyOp({}, { op: 'increment', key: 'a' }), 'increment');
});

test('appendOp writes one JSON line per operation', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'wal.jsonl');
    await appendOp(file, { op: 'set', key: 'a', value: 1 });
    await appendOp(file, { op: 'delete', key: 'a' });
    eq(
      await fs.readFile(file, 'utf8'),
      '{"op":"set","key":"a","value":1}\n{"op":"delete","key":"a"}\n'
    );
  });
});

test('replaying a missing log gives empty state', async () => {
  await withTempDir(async (dir) => {
    eq(await replayLog(path.join(dir, 'wal.jsonl')), {});
  });
});

test('replay rebuilds the state, last write winning', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'wal.jsonl');
    await appendOp(file, { op: 'set', key: 'theme', value: 'light' });
    await appendOp(file, { op: 'set', key: 'font', value: 14 });
    await appendOp(file, { op: 'set', key: 'theme', value: 'dark' });
    await appendOp(file, { op: 'delete', key: 'font' });
    eq(await replayLog(file), { theme: 'dark' });
  });
});

test('a crash mid-append costs the last op and nothing else', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'wal.jsonl');
    await appendOp(file, { op: 'set', key: 'a', value: 1 });
    await appendOp(file, { op: 'set', key: 'b', value: 2 });
    await appendOp(file, { op: 'set', key: 'c', value: 3 });
    await truncateBy(file, 12); // the 'c' line is now half-written
    const raw = await fs.readFile(file, 'utf8');
    ok(!raw.endsWith('\n'), 'the fixture must really be torn');
    eq(await replayLog(file), { a: 1, b: 2 });
  });
});

test('the log keeps growing — replay is what collapses it', async () => {
  await withTempDir(async (dir) => {
    const file = path.join(dir, 'wal.jsonl');
    for (let i = 0; i < 6; i += 1) {
      await appendOp(file, { op: 'set', key: 'hits', value: i });
    }
    const lines = (await fs.readFile(file, 'utf8')).trim().split('\n');
    eq(lines.length, 6); // six writes on disk…
    eq(await replayLog(file), { hits: 5 }); // …one key in memory
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('an empty store loads as empty state', async () => {
  await withTempDir(async (dir) => {
    eq(await loadState(dir, 'kv'), {});
  });
});

test('loadState replays the log when there is no snapshot yet', async () => {
  await withTempDir(async (dir) => {
    await appendOp(dir, 'kv', { op: 'set', key: 'a', value: 1 });
    await appendOp(dir, 'kv', { op: 'set', key: 'b', value: 2 });
    await appendOp(dir, 'kv', { op: 'delete', key: 'a' });
    eq(await loadState(dir, 'kv'), { b: 2 });
  });
});

test('compaction preserves the state exactly', async () => {
  await withTempDir(async (dir) => {
    await appendOp(dir, 'kv', { op: 'set', key: 'theme', value: 'dark' });
    await appendOp(dir, 'kv', { op: 'set', key: 'font', value: 14 });
    const before = await loadState(dir, 'kv');
    eq(await compact(dir, 'kv'), before);
    eq(await loadState(dir, 'kv'), before);
  });
});

test('compaction empties the log and fills the snapshot', async () => {
  await withTempDir(async (dir) => {
    await appendOp(dir, 'kv', { op: 'set', key: 'a', value: 1 });
    await compact(dir, 'kv');
    eq((await fs.stat(logPath(dir, 'kv'))).size, 0);
    eq(JSON.parse(await fs.readFile(snapshotPath(dir, 'kv'), 'utf8')), { a: 1 });
  });
});

test('ops after a compaction land on top of the snapshot', async () => {
  await withTempDir(async (dir) => {
    await appendOp(dir, 'kv', { op: 'set', key: 'a', value: 1 });
    await compact(dir, 'kv');
    await appendOp(dir, 'kv', { op: 'set', key: 'b', value: 2 });
    await appendOp(dir, 'kv', { op: 'delete', key: 'a' });
    eq(await loadState(dir, 'kv'), { b: 2 });
  });
});

test('compacting twice is safe and keeps the log empty', async () => {
  await withTempDir(async (dir) => {
    await appendOp(dir, 'kv', { op: 'set', key: 'a', value: 1 });
    await compact(dir, 'kv');
    await compact(dir, 'kv');
    eq(await loadState(dir, 'kv'), { a: 1 });
    eq((await fs.stat(logPath(dir, 'kv'))).size, 0);
  });
});

test('a compacted store starts up with one line instead of many', async () => {
  await withTempDir(async (dir) => {
    // the same bytes 50 appendOp calls would leave behind, written in one
    // go — 50 round trips to a busy disk is the test being slow, not the
    // code being tested.
    const ops = Array.from({ length: 50 }, (_, i) =>
      JSON.stringify({ op: 'set', key: 'hits', value: i })
    );
    await fs.appendFile(logPath(dir, 'kv'), `${ops.join('\n')}\n`, 'utf8');
    const raw = await readOrNull(logPath(dir, 'kv'));
    ok(raw.split('\n').length > 50, 'the log really is long before compaction');
    await compact(dir, 'kv');
    eq(await loadState(dir, 'kv'), { hits: 49 });
    eq(await readOrNull(logPath(dir, 'kv')), '');
  });
});

test('the snapshot is written atomically — no temp files survive', async () => {
