  eq(stableStringify({ b: 1, a: 2, c: 3 }), '{"a":2,"b":1,"c":3}');
});

test('sorts keys at every depth', () => {
  eq(
    stableStringify({ outer: { z: 1, a: { y: 2, b: 3 } } }),
    '{"outer":{"a":{"b":3,"y":2},"z":1}}'
  );
});

