export const logPath = (dir, name) => path.join(dir, `${name}.log`);

export function applyOp(state, op) {
  if (op.op === 'set') state[op.key] = op.value;
  else if (op.op === 'delete') delete state[op.key];
  else throw new Error(`unknown log op: ${op.op}`);
  return state;
}

