  await withTempDir(async (dir) => {
    await acquireLock(dir, { pid: 4242, now: () => 1_000, staleMs: 30_000 });
    const file = await acquireLock(dir, {
      pid: 7,
      now: () => 1_000 + 30_001,
      staleMs: 30_000,
    });
    eq(file, lockPath(dir));
    eq(await readLock(dir), { pid: 7, at: 31_001 });
  });
});

