  withDb((db) => {
    withTransaction(db, () => {
      const insert = db.prepare('INSERT INTO accounts VALUES (?, ?)');
      insert.run('cleo', 5);
      insert.run('dana', 7);
    });
    eq(totalMoney(db), 162);
  });
});

